/**
 * HTMB - Hypertext Markup Builder
 * Types for index.js, index.mjs and htmb.umd.js
 */
declare namespace htmb {
  /**
   * An attribute value. `true` writes a bare attribute like `disabled`;
   * `false`, `null` and `undefined` leave the attribute out.
   */
  type AttributeValue = string | number | boolean | null | undefined;

  /** A tag's attributes, by name. */
  type Attributes = Record<string, AttributeValue>;

  /**
   * A tag's child. Strings and numbers go into the HTML as is;
   * `null` and `undefined` are skipped.
   */
  type Child = string | number | null | undefined;

  /**
   * Builds one tag and returns its HTML. Attributes are optional and go
   * first, so `div("text")` and `div({ class: "box" }, "text")` both work.
   */
  type TagFunction = (
    attributes?: Attributes | Child,
    ...children: Child[]
  ) => string;

  interface Htmb {
    // tags below are generated by generate.js from documentation/html.json
    area: TagFunction;
    base: TagFunction;
    br: TagFunction;
    col: TagFunction;
    embed: TagFunction;
    hr: TagFunction;
    img: TagFunction;
    input: TagFunction;
    link: TagFunction;
    meta: TagFunction;
    source: TagFunction;
    track: TagFunction;
    wbr: TagFunction;

    a: TagFunction;
    abbr: TagFunction;
    address: TagFunction;
    article: TagFunction;
    aside: TagFunction;
    audio: TagFunction;
    b: TagFunction;
    bdi: TagFunction;
    bdo: TagFunction;
    blockquote: TagFunction;
    body: TagFunction;
    button: TagFunction;
    canvas: TagFunction;
    caption: TagFunction;
    cite: TagFunction;
    code: TagFunction;
    colgroup: TagFunction;
    data: TagFunction;
    datalist: TagFunction;
    dd: TagFunction;
    del: TagFunction;
    details: TagFunction;
    dfn: TagFunction;
    dialog: TagFunction;
    div: TagFunction;
    dl: TagFunction;
    dt: TagFunction;
    em: TagFunction;
    fieldset: TagFunction;
    figcaption: TagFunction;
    figure: TagFunction;
    footer: TagFunction;
    form: TagFunction;
    h1: TagFunction;
    head: TagFunction;
    header: TagFunction;
    hgroup: TagFunction;
    html: TagFunction;
    i: TagFunction;
    ins: TagFunction;
    kbd: TagFunction;
    label: TagFunction;
    legend: TagFunction;
    li: TagFunction;
    main: TagFunction;
    map: TagFunction;
    mark: TagFunction;
    menu: TagFunction;
    meter: TagFunction;
    nav: TagFunction;
    noscript: TagFunction;
    object: TagFunction;
    ol: TagFunction;
    optgroup: TagFunction;
    option: TagFunction;
    output: TagFunction;
    p: TagFunction;
    picture: TagFunction;
    pre: TagFunction;
    progress: TagFunction;
    q: TagFunction;
    rp: TagFunction;
    rt: TagFunction;
    ruby: TagFunction;
    s: TagFunction;
    samp: TagFunction;
    script: TagFunction;
    search: TagFunction;
    section: TagFunction;
    select: TagFunction;
    selectedcontent: TagFunction;
    slot: TagFunction;
    small: TagFunction;
    span: TagFunction;
    strong: TagFunction;
    style: TagFunction;
    sub: TagFunction;
    summary: TagFunction;
    sup: TagFunction;
    table: TagFunction;
    tbody: TagFunction;
    td: TagFunction;
    textarea: TagFunction;
    tfoot: TagFunction;
    th: TagFunction;
    thead: TagFunction;
    time: TagFunction;
    title: TagFunction;
    tr: TagFunction;
    u: TagFunction;
    ul: TagFunction;
    var: TagFunction;
    video: TagFunction;
    h2: TagFunction;
    h3: TagFunction;
    h4: TagFunction;
    h5: TagFunction;
    h6: TagFunction;
    iframe: TagFunction;
    template: TagFunction;
    // end of generated tags

    /**
     * Returns `text` with `&`, `<`, `>`, `"` and `'` replaced by entities.
     * `null` and `undefined` become an empty string.
     */
    escape: (text: string | number | null | undefined) => string;
  }
}

declare const htmb: htmb.Htmb;
export = htmb;
